import sys
import math

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        N = int(sys.stdin.readline())
        A = []
        for i in range(1, N+1):
            A.append(i)
        for i in range(1, N):
            A.append(math.lcm(A[i-1], A[i]))
        print(' '.join(map(str, A[:N])))

solve()
